const hours = 730;
const serverPrice = 0.05;
const requests = 7200000;
const perRequest = 0.000002;
const server = hours * serverPrice;
const serverless = requests * perRequest;
console.log('server: $' + server.toFixed(2));
console.log('serverless: $' + serverless.toFixed(2));
console.log('cheaper: ' + (serverless < server ? 'serverless' : 'server'));

